input.script:
const corazon = document.getElementById('corazon');
const UMBRAL = 100;

function setFrecuencia(bpm) {
  const alta = bpm > UMBRAL;
  corazon.style.setProperty('--color', alta ? '#ff0000' : '#047f00');
  corazon.style.animationDuration = (60 / bpm) + 's';
  document.getElementById('valor').textContent = bpm;
}

document.getElementById('slider').addEventListener('input', e => {
  setFrecuencia(Number(e.target.value));
});

setFrecuencia(70);
